"""Reproducibility checks for the exact expected RSFW section-efficiency bound.

Analytic proof is in RESULT.md; sampled checks are diagnostic only.
No external dependencies are required.
"""
from fractions import Fraction
from math import cos, sin, sqrt
from random import Random


def haar_frame(n, d, rng):
    """Columns generated by Gaussian Gram--Schmidt: Haar d-frame in R^n."""
    cols = []
    for j in range(d):
        z = [rng.gauss(0, 1) for _ in range(n)]
        for q in cols:
            p = sum(a*b for a, b in zip(z, q))
            z = [a-p*b for a, b in zip(z, q)]
        mag = sqrt(sum(a*a for a in z))
        cols.append([a/mag for a in z])
    return cols


def sample(n, d, theta, draws, rng):
    mean_r = mean_derivative = mean_gap = 0.0
    for _ in range(draws):
        cols = haar_frame(n, d, rng)
        a = [q[0] for q in cols]
        b = [q[1] for q in cols]
        r = sum(t*t for t in a)
        dp = sum(x*y for x, y in zip(a, b))
        v = [cos(theta)*x+sin(theta)*y for x, y in zip(a, b)]
        fv = sqrt(sum(t*t for t in v))
        fu = sqrt(r)
        mean_r += r
        mean_derivative += dp*dp/r
        mean_gap += (fu-fv)**2/(2*(1-cos(theta)))
    return mean_r/draws, mean_derivative/draws, mean_gap/draws


def main():
    # Exact, parameter-exhaustive rational verification of the proof's moment
    # identity and claimed sharp coefficient over these dimensions.
    for n in range(2, 201):
        for d in range(1, n+1):
            projection_moment = Fraction(d, n)
            tangent_moment = (1-projection_moment)/(n-1)
            exact_bound = projection_moment-tangent_moment
            assert exact_bound == Fraction(d-1, n-1)
            assert 0 <= exact_bound <= 1
    rng = Random(271828)
    for n, d in ((3, 2), (10, 2), (10, 5), (15, 3)):
        projection, tangent, deficit = sample(n, d, .03, 3000, rng)
        expected_proj = d/n
        expected_tangent = (n-d)/(n*(n-1))
        # Loose Monte Carlo tolerances, not certificates of the theorem.
        assert abs(projection-expected_proj) < .045
        assert abs(tangent-expected_tangent) < .04
        assert abs(deficit-expected_tangent) < .04
        print(f'n={n},d={d} projected={projection:.6f}, tangent={tangent:.6f}, chord_deficit={deficit:.6f}, exact={expected_tangent:.6f}')
    print('VERIFY_OK (finite diagnostics only; analytic proof in RESULT.md)')


if __name__ == '__main__':
    main()
